def find_all_json(dir_path, max_depth=3):
    """Find all json files given a directory path"""
    found = []
    for root, dirs, files in os.walk(dir_path, topdown=True):
        # Limit depth
        level = root.replace(dir_path, '').count(os.sep)
        if level >= max_depth:
            continue
        for f in files:
            if f.endswith('.json'):
                found.append(os.path.join(root, f))
    return found

